// Process restaurant search results and filter based on dietary requirements
const searchResults = $input.first().json.businesses || [];
const userPrefs = $('Webhook Trigger').first().json.body;

const processedRestaurants = searchResults.map(restaurant => {
  const processed = {
    id: restaurant.id,
    name: restaurant.name,
    rating: restaurant.rating,
    reviewCount: restaurant.review_count,
    priceRange: restaurant.price,
    cuisine: restaurant.categories?.map(cat => cat.title).join(', '),
    address: formatAddress(restaurant.location),
    phone: restaurant.phone,
    imageUrl: restaurant.image_url,
    url: restaurant.url,
    distance: Math.round(restaurant.distance * 3.28084) + ' ft', // Convert meters to feet
    isOpen: restaurant.is_closed === false,
    coordinates: restaurant.coordinates
  };

  // Add dietary compatibility score
  processed.dietaryCompatibility = calculateDietaryScore(restaurant, userPrefs);
  processed.partyCompatibility = calculatePartySizeScore(restaurant, userPrefs.partySize);

  return processed;
});

// Sort by compatibility scores and rating
const sortedRestaurants = processedRestaurants
  .filter(r => r.dietaryCompatibility.score > 0.3) // Filter out incompatible restaurants
  .sort((a, b) => {
    const scoreA = (a.dietaryCompatibility.score * 0.4) + (a.partyCompatibility.score * 0.3) + (a.rating * 0.3);
    const scoreB = (b.dietaryCompatibility.score * 0.4) + (b.partyCompatibility.score * 0.3) + (b.rating * 0.3);
    return scoreB - scoreA;
  })
  .slice(0, 10); // Top 10 recommendations

return [{
  restaurants: sortedRestaurants,
  searchCriteria: userPrefs,
  totalFound: searchResults.length,
  recommendations: generateRecommendationSummary(sortedRestaurants, userPrefs)
}];

function formatAddress(location) {
  if (!location) return 'Address not available';
  return `${location.address1 || ''} ${location.city || ''}, ${location.state || ''} ${location.zip_code || ''}`.trim();
}

function calculateDietaryScore(restaurant, prefs) {
  const dietaryReqs = prefs.dietaryRequirements || [];
  const cuisine = restaurant.categories?.map(cat => cat.title.toLowerCase()).join(' ') || '';
  const name = restaurant.name.toLowerCase();

  let score = 1.0; // Start with full compatibility
  let reasons = [];

  dietaryReqs.forEach(req => {
    const requirement = req.toLowerCase();

    if (requirement === 'vegetarian') {
      if (cuisine.includes('vegetarian') || cuisine.includes('vegan') || cuisine.includes('salad')) {
        reasons.push('Vegetarian-friendly cuisine');
      } else if (cuisine.includes('steakhouse') || cuisine.includes('bbq')) {
        score -= 0.4;
        reasons.push('Limited vegetarian options expected');
      } else {
        score -= 0.2;
      }
    }

    if (requirement === 'vegan') {
      if (cuisine.includes('vegan') || name.includes('vegan')) {
        reasons.push('Vegan-friendly restaurant');
      } else if (cuisine.includes('vegetarian')) {
        score -= 0.1;
        reasons.push('Vegetarian restaurant - likely has vegan options');
      } else {
        score -= 0.3;
        reasons.push('Vegan options may be limited');
      }
    }

    if (requirement === 'gluten-free') {
      if (name.includes('gluten') || cuisine.includes('health')) {
        reasons.push('Likely gluten-free options available');
      } else {
        score -= 0.1;
        reasons.push('Gluten-free options may be available upon request');
      }
    }

    if (requirement === 'halal') {
      if (cuisine.includes('halal') || cuisine.includes('middle eastern') || cuisine.includes('mediterranean')) {
        reasons.push('Halal cuisine available');
      } else {
        score -= 0.2;
      }
    }
  });

  return {
    score: Math.max(0.1, score), // Minimum score of 0.1
    reasons: reasons
  };
}

function calculatePartySizeScore(restaurant, partySize) {
  const size = parseInt(partySize) || 2;
  let score = 1.0;
  let reasons = [];

  if (size <= 2) {
    score = 1.0;
    reasons.push('Perfect for intimate dining');
  } else if (size <= 4) {
    score = 0.9;
    reasons.push('Good for small groups');
  } else if (size <= 8) {
    score = 0.7;
    reasons.push('May require reservation for larger group');
  } else {
    score = 0.5;
    reasons.push('Large group - call ahead recommended');
  }

  return {
    score: score,
    reasons: reasons
  };
}

function generateRecommendationSummary(restaurants, prefs) {
  if (restaurants.length === 0) {
    return {
      summary: 'No restaurants found matching your criteria. Try expanding your search radius or dietary requirements.',
      tips: ['Consider broadening cuisine preferences', 'Check if location is correct', 'Try searching without dietary filters first']
    };
  }

  const topChoice = restaurants[0];
  const avgRating = (restaurants.reduce((sum, r) => sum + r.rating, 0) / restaurants.length).toFixed(1);

  return {
    summary: `Found ${restaurants.length} great options! Top recommendation: ${topChoice.name} (${topChoice.rating}⭐)`,
    avgRating: avgRating,
    priceRange: getMostCommonPriceRange(restaurants),
    tips: generatePersonalizedTips(restaurants, prefs)
  };
}

function getMostCommonPriceRange(restaurants) {
  const priceCount = {};
  restaurants.forEach(r => {
    const price = r.priceRange || '$';
    priceCount[price] = (priceCount[price] || 0) + 1;
  });

  return Object.keys(priceCount).reduce((a, b) => priceCount[a] > priceCount[b] ? a : b);
}

function generatePersonalizedTips(restaurants, prefs) {
  const tips = [];

  if (prefs.dietaryRequirements?.length > 0) {
    tips.push('Call ahead to confirm dietary accommodations');
  }

  if (parseInt(prefs.partySize) > 6) {
    tips.push('Make reservations in advance for your group size');
  }

  if (prefs.occasion) {
    tips.push(`Perfect for ${prefs.occasion} - check dress code if applicable`);
  }

  tips.push('Check recent reviews for current menu and service quality');

  return tips;
}

