// Process menu recommendations and restaurant details
const menuAI = $('Menu Recommendations').first()?.json?.message?.content || '';
const restaurantDetails = $('Restaurant Details').first()?.json || {};
const userPrefs = $('Webhook Trigger').first().json.body;

const menuData = {
  restaurantInfo: {
    name: restaurantDetails.name,
    rating: restaurantDetails.rating,
    priceRange: restaurantDetails.price,
    cuisine: restaurantDetails.categories?.map(cat => cat.title).join(', '),
    hours: formatHours(restaurantDetails.hours),
    phone: restaurantDetails.phone,
    address: formatAddress(restaurantDetails.location),
    photos: restaurantDetails.photos?.slice(0, 5) || [],
    specialFeatures: extractSpecialFeatures(restaurantDetails)
  },
  recommendations: parseMenuRecommendations(menuAI),
  dietaryAccommodations: parseDietaryInfo(menuAI, userPrefs.dietaryRequirements),
  orderingSuggestions: parseOrderingSuggestions(menuAI),
  reservationInfo: generateReservationInfo(restaurantDetails, userPrefs),
  personalizedTips: generatePersonalizedDiningTips(restaurantDetails, userPrefs)
};

return [menuData];

function formatHours(hours) {
  if (!hours || !hours[0] || !hours[0].open) return 'Hours not available';

  const todayHours = hours[0].open[new Date().getDay()];
  if (!todayHours) return 'Closed today';

  const openTime = formatTime(todayHours.start);
  const closeTime = formatTime(todayHours.end);

  return `${openTime} - ${closeTime}`;
}

function formatTime(timeStr) {
  const hour = parseInt(timeStr.slice(0, 2));
  const minute = timeStr.slice(2, 4);
  const ampm = hour >= 12 ? 'PM' : 'AM';
  const displayHour = hour > 12 ? hour - 12 : (hour === 0 ? 12 : hour);
  return `${displayHour}:${minute} ${ampm}`;
}

function formatAddress(location) {
  if (!location) return 'Address not available';
  return `${location.address1 || ''} ${location.city || ''}, ${location.state || ''} ${location.zip_code || ''}`.trim();
}

function extractSpecialFeatures(restaurant) {
  const features = [];
  const attributes = restaurant.attributes || {};

  if (attributes.has_tv) features.push('TV Available');
  if (attributes.outdoor_seating) features.push('Outdoor Seating');
  if (attributes.takes_reservations) features.push('Accepts Reservations');
  if (attributes.delivery) features.push('Delivery Available');
  if (attributes.wheelchair_accessible) features.push('Wheelchair Accessible');
  if (attributes.good_for_groups) features.push('Great for Groups');
  if (attributes.has_wifi) features.push('WiFi Available');

  return features;
}

function parseMenuRecommendations(aiResponse) {
  const sections = aiResponse.split(/\n(?=[A-Z][a-z]*:)|(?:Recommendations?:|Dishes?:)/i);
  const recommendations = [];

  sections.forEach(section => {
    const lines = section.split('\n').filter(line => line.trim());
    if (lines.length > 1) {
      const category = lines[0].replace(':', '').trim();
      const items = lines.slice(1).map(line => {
        const cleanLine = line.replace(/^[-•*\d.\s]+/, '').trim();
        return {
          name: extractDishName(cleanLine),
          description: cleanLine,
          category: category
        };
      });

      recommendations.push({
        category: category,
        items: items.slice(0, 3) // Limit to 3 items per category
      });
    }
  });

  return recommendations.slice(0, 4); // Limit to 4 categories
}

function extractDishName(description) {
  // Extract dish name (usually first few words before a dash or description)
  const match = description.match(/^([^-–,]+)/);
  return match ? match[1].trim() : description.split(' ').slice(0, 3).join(' ');
}

function parseDietaryInfo(aiResponse, requirements) {
  const dietaryInfo = {};

  (requirements || []).forEach(req => {
    const reqLower = req.toLowerCase();
    const pattern = new RegExp(`${reqLower}[^\n]*(?:\n[^\n]*){0,2}`, 'gi');
    const matches = aiResponse.match(pattern);

    if (matches) {
      dietaryInfo[req] = matches.join(' ').slice(0, 200) + '...';
    } else {
      dietaryInfo[req] = `Ask your server about ${req} options - most restaurants can accommodate this dietary requirement.`;
    }
  });

  return dietaryInfo;
}

function parseOrderingSuggestions(aiResponse) {
  const suggestions = [];
  const orderingSection = aiResponse.match(/(?:ordering|tips|suggestions)[\s\S]*?(?=\n\n|$)/i);

  if (orderingSection) {
    const lines = orderingSection[0].split('\n');
    lines.forEach(line => {
      if (line.match(/^[-•*\d.\s]/)) {
        suggestions.push(line.replace(/^[-•*\d.\s]+/, '').trim());
      }
    });
  }

  // Default suggestions if none found
  if (suggestions.length === 0) {
    suggestions.push(
      'Ask your server for daily specials and seasonal dishes',
      'Consider sharing appetizers to try more variety',
      'Don\'t hesitate to ask about preparation methods for dietary needs'
    );
  }

  return suggestions.slice(0, 5);
}

function generateReservationInfo(restaurant, prefs) {
  const partySize = parseInt(prefs.partySize) || 2;
  const info = {
    recommended: partySize > 4 || prefs.occasion === 'special',
    phone: restaurant.phone,
    onlineBooking: 'Check restaurant website or OpenTable',
    timing: generateTimingAdvice(partySize, prefs.occasion)
  };

  return info;
}

function generateTimingAdvice(partySize, occasion) {
  let advice = 'Call ahead for availability';

  if (partySize > 6) {
    advice = '24-48 hours advance notice recommended';
  } else if (occasion === 'special' || occasion === 'date') {
    advice = 'Book 1-2 days in advance for preferred timing';
  } else if (partySize <= 2) {
    advice = 'Same day reservations often available';
  }

  return advice;
}

function generatePersonalizedDiningTips(restaurant, prefs) {
  const tips = [];

  const rating = restaurant.rating || 4.0;
  if (rating >= 4.5) {
    tips.push('Highly rated - expect excellent service and food quality');
  }

  const priceRange = restaurant.price;
  if (priceRange === '$$$$') {
    tips.push('Fine dining establishment - dress code may apply');
  } else if (priceRange === '$') {
    tips.push('Casual dining - great value for money');
  }

  if (prefs.occasion === 'business') {
    tips.push('Professional atmosphere suitable for business meetings');
  } else if (prefs.occasion === 'date') {
    tips.push('Romantic ambiance perfect for special occasions');
  }

  if (parseInt(prefs.partySize) > 8) {
    tips.push('Large group - consider family-style ordering for sharing');
  }

  tips.push('Check their social media for latest menu updates and specials');

  return tips;
}

// Generate reservation assistance and booking information
const userRequest = $('Webhook Trigger').first().json.body;

const reservationAssistance = {
  restaurantName: userRequest.restaurantName,
  requestDetails: {
    partySize: userRequest.partySize,
    preferredDate: userRequest.preferredDate,
    preferredTime: userRequest.preferredTime,
    specialRequests: userRequest.specialRequests || [],
    dietaryRequirements: userRequest.dietaryRequirements || []
  },
  bookingOptions: [
    {
      method: 'Phone',
      contact: userRequest.restaurantPhone,
      description: 'Call directly for immediate confirmation',
      pros: ['Immediate confirmation', 'Can discuss special requests', 'Personal service'],
      cons: ['May need to call during business hours', 'Potential wait time']
    },
    {
      method: 'OpenTable',
      contact: 'https://www.opentable.com',
      description: 'Online reservation platform',
      pros: ['24/7 availability', 'Instant confirmation', 'Easy to modify'],
      cons: ['Limited availability shown', 'May not handle special requests']
    },
    {
      method: 'Restaurant Website',
      contact: userRequest.restaurantWebsite,
      description: 'Direct booking through restaurant site',
      pros: ['Restaurant-specific options', 'Direct communication', 'Latest availability'],
      cons: ['May redirect to third-party platforms']
    }
  ],
  preparationChecklist: generatePreparationChecklist(userRequest),
  followUpReminders: [
    {
      timing: '24 hours before',
      action: 'Confirm reservation and review special requests'
    },
    {
      timing: '2 hours before',
      action: 'Check traffic and parking options'
    },
    {
      timing: 'Day of',
      action: 'Call if running more than 15 minutes late'
    }
  ]
};

return [reservationAssistance];

function generatePreparationChecklist(request) {
  const checklist = [];

  // Party size considerations
  if (parseInt(request.partySize) > 6) {
    checklist.push({
      item: 'Confirm large party policies and potential gratuity charges',
      category: 'Group Size'
    });
  }

  // Dietary requirements
  if (request.dietaryRequirements?.length > 0) {
    checklist.push({
      item: `Inform restaurant about dietary requirements: ${request.dietaryRequirements.join(', ')}`,
      category: 'Dietary Needs'
    });
  }

  // Special occasions
  if (request.occasion) {
    checklist.push({
      item: `Mention special occasion (${request.occasion}) for potential complimentary touches`,
      category: 'Special Requests'
    });
  }

  // General preparation
  checklist.push(
    {
      item: 'Check dress code requirements',
      category: 'Preparation'
    },
    {
      item: 'Review menu online to save time',
      category: 'Preparation'
    },
    {
      item: 'Plan parking or transportation',
      category: 'Logistics'
    }
  );

  return checklist;
}
